117	const NetworkTab = () => {
118	  const dispatch = useDispatch();
119	  const { networkFilters, selectedRequest } = useSelector((state) => state.logs);
120	  const collections = useSelector((state) => state.collections.collections);
121	
122	  const allRequests = useMemo(() => {
123	    const requests = [];
124	
125	    collections.forEach((collection) => {
126	      if (collection.timeline) {
127	        collection.timeline
128	          .filter((entry) => entry.type === 'request')
129	          .forEach((entry) => {
130	            requests.push({
131	              ...entry,
132	              collectionName: collection.name,
133	              collectionUid: collection.uid
134	            });
135	          });
136	      }
137	    });
138	
139	    return requests.sort((a, b) => a.timestamp - b.timestamp);
140	  }, [collections]);
141	
142	  const filteredRequests = useMemo(() => {
143	    return allRequests.filter((request) => {
144	      const method = request.data?.request?.method?.toUpperCase() || 'GET';
145	      return networkFilters[method];
146	    });
147	  }, [allRequests, networkFilters]);
148	
149	  const handleRequestClick = (request) => {
150	    dispatch(setSelectedRequest(request));
151	  };
152	
153	  return (
154	    <StyledWrapper>
155	      <div className="network-content">
156	        {filteredRequests.length === 0 ? (
157	          <div className="network-empty">
158	            <IconNetwork size={48} strokeWidth={1} />
159	            <p>No network requests</p>
160	            <span>Requests will appear here as you make API calls</span>
161	          </div>
162	        ) : (
163	          <div className="requests-container">
164	            <div className="requests-header">
165	              <div>Method</div>
166	              <div>Status</div>
167	              <div>Domain</div>
168	              <div>Path</div>
169	              <div>Time</div>
170	              <div className="text-right">Duration</div>
171	              <div className="text-right">Size</div>
172	            </div>
173	
174	            <div className="requests-list">
175	              {filteredRequests.map((request, index) => (
176	                <RequestRow
177	                  key={`${request.collectionUid}-${request.itemUid}-${request.timestamp}-${index}`}
178	                  request={request}
179	                  isSelected={selectedRequest?.timestamp === request.timestamp && selectedRequest?.itemUid === request.itemUid}
180	                  onClick={() => handleRequestClick(request)}
181	                />
182	              ))}
183	            </div>
184	          </div>
185	        )}
186	      </div>
187	    </StyledWrapper>
188	  );
189	};
190	
191	export default NetworkTab;
