import { createSlice } from '@reduxjs/toolkit';

export const TABS = {
  CONSOLE: 'console',
  NETWORK: 'network',
  PERFORMANCE: 'performance',
  TERMINAL: 'terminal'
};

export const TAB_IDENFIERS = Object.values(TABS);

const initialState = {
  logs: [],
  debugErrors: [],
  isConsoleOpen: false,
  activeTab: 'console',
  filters: {
    info: true,
    warn: true,
    error: true,
    debug: true,
    log: true
  },
  networkFilters: {
    GET: true,
    POST: true,
    PUT: true,
    DELETE: true,
    PATCH: true,
    HEAD: true,
    OPTIONS: true
  },
  selectedRequest: null,
  selectedError: null,
  maxLogs: 1000,
  maxDebugErrors: 500
};

export const logsSlice = createSlice({
  name: 'logs',
  initialState,
  reducers: {
    addLog: (state, action) => {
      const { type, args, timestamp } = action.payload;
      const newLog = {
        id: Date.now() + Math.random(),
        type: type || 'log',
        message: args ? args.join(' ') : '',
        args: args || [],
        timestamp: timestamp || new Date().toISOString()
      };

      state.logs.push(newLog);

      if (state.logs.length > state.maxLogs) {
        state.logs = state.logs.slice(-state.maxLogs);
      }
    },
    addDebugError: (state, action) => {
      const { message, stack, filename, lineno, colno, args, timestamp } = action.payload;
      const newError = {
        id: Date.now() + Math.random(),
        message: message || 'Unknown error',
        stack: stack,
        filename: filename,
        lineno: lineno,
        colno: colno,
        args: args || [],
        timestamp: timestamp || new Date().toISOString()
      };

      state.debugErrors.push(newError);

      if (state.debugErrors.length > state.maxDebugErrors) {
        state.debugErrors = state.debugErrors.slice(-state.maxDebugErrors);
      }
    },
